    hProgramMode = CreateEvent (NULL, TRUE, FALSE, eventname);
    if (hProgramMode == NULL) 
    {
        _tprintf(_T("Bad program mode event handle\n"));
        _tprintf(_T("GetLastError() = %d\n"), GetLastError());
        return 1;
    }
    else
    {
